import json
from test import ANY, unittest, Mock
from taf.cloud.cbam.vnf.v3.vnf import VNF3

from taf.cloud.cbam.schemas.v3.operation_execution import OperationExecution
from taf.cloud.cbam.schemas.v3.vim_info import VimInfo, OpenstackV2Info
from taf.cloud.cbam.schemas.vnf_info import VnfInfo
from taf.cloud.cbam.schemas.problem_details import ProblemDetails
from taf.cloud.cbam.session import CbamResponse, CbamSession
from taf.cloud.cbam import exception


class TestVNF(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        self.vnf = VNF3(self.m_client)

    def vnf_info_dict(self):
        return {'id': 'id', 'vnfdId': 'vnfdId', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                'vnfdVersion': 'vnfdVersion', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId',
                'instantiationState': 'instantiationState'}

    def vnf_info__list_of_dicts(self):
        return [{'id': 'id', 'vnfdId': 'vnfdId', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                 'vnfdVersion': 'vnfdVersion', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId',
                 'instantiationState': 'instantiationState', 'name': 'name'},
                {'id': 'id2', 'vnfdId': 'vnfdId2', 'vnfSoftwareVersion': 'vnfSoftwareVersion2',
                 'vnfdVersion': 'vnfdVersion2', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId2',
                 'instantiationState': 'instantiationState2', 'name': 'name2'}]

    def test_createVnf_requestSend(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=self.vnf_info_dict()), status_code=201))

        vnf_info = VnfInfo(vnfd_id=4, name='vnf4', description='it is vnf')
        resp = self.vnf.create(vnf_info)

        data = {'description': 'it is vnf', 'vnfdId': 4, 'name': 'vnf4'}
        expected_url = 'vnfm/lcm/v3/vnfs'
        actual_data = json.loads(self.m_client.send_request.call_args[1]['data'])
        actual_url = self.m_client.send_request.call_args[1]['endpoint']

        self.assertEqual(expected_url, actual_url)
        self.assertDictEqual(data, actual_data)
        self.assertIsInstance(resp, VnfInfo)

    def test_queryOne_requestSendResponseReceived(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=self.vnf_info_dict()), status_code=200))

        vnf_info = Mock()
        vnf_info.id = 42
        resp = self.vnf.query_one(vnf_info)

        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='get', endpoint='vnfm/lcm/v3/vnfs/42')

        self.assertIsInstance(resp, VnfInfo)

    def test_queryAllVNfs_requestSendResponseReceived(self):
        status_code = 200
        output = self.vnf_info__list_of_dicts()
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        resp = self.vnf.query_all_vnfs()
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='get', endpoint='vnfm/lcm/v3/vnfs')
        for vnf_info in resp:
            self.assertIsInstance(vnf_info, VnfInfo)

    def test_givenValidVnfName_deleteVnf_shouldPass(self):
        self.m_client.send_request.side_effect = [
            CbamResponse(Mock(json=Mock(
                return_value=self.vnf_info__list_of_dicts()), status_code=200)),
            CbamResponse(Mock(json=Mock(return_value={}), status_code=204))
        ]
        vnf_info = Mock()
        vnf_info.name = 'name'
        self.vnf.delete_vnf(vnf_info)

    def test_givenInvalidVnfName_delete_shouldRaiseException(self):
        self.m_client.send_request = Mock(
            return_value=CbamResponse(
                Mock(json=Mock(return_value=self.vnf_info__list_of_dicts()),
                     status_code=200)))

        with self.assertRaises(exception.VnfNameNotFoundException):
            self.vnf.delete_vnf(Mock(name='other name'))

    def test_getVimInfo_returnRightParams(self):
        json_response = {'id': 'vim_id',
                         'vimInfoType': 'OPENSTACK_V2_INFO',
                         'interfaceInfo': {'endpoint': 'vnfm/lcm/v3/vnfs/vnf_id/vim_info/vim_id'},
                         'accessInfo': {'region': 'Region', 'tenant': 'Tenant',
                                        'username': 'Username', 'password': 'Password'}}
        self.m_client.send_request.side_effect = [
            CbamResponse(Mock(json=Mock(return_value=self.vnf_info__list_of_dicts()),
                              status_code=200)),
            CbamResponse(Mock(json=Mock(return_value=json_response),
                              status_code=200))]

        response = self.vnf.get_vim_info(VnfInfo(name='name'), VimInfo(id='vim_id'))

        self.assertIsInstance(response, OpenstackV2Info)
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='get', endpoint='vnfm/lcm/v3/vnfs/id/vim_info/vim_id')


class TestVnfLifecycle(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        # self.m_client = CbamSession('ip', False)
        self.vnf = VNF3(self.m_client)

        vnf = Mock()
        vnf.id = 'id'
        vnf.name = 'some name'

        self.vnf.query_all_vnfs = Mock(return_value=[vnf])

        self.input_data = {'some key': 'some value'}

    def operation_execution_dict(self):
        return {'id': 'opeartionId', 'vnfInstanceId': 'vnfID',
                'operationType': 'operationType', 'status': 'status',
                'isCancelPending': 'isCancelPending', 'startTime': 'startTime',
                '_links': {'self': {'href': 'self'}}}

    def test_givenValidArgs_instantiateVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnfm/lcm/v3/vnfs/id/instantiate'
        json_content = {'id': 'id',
                        'vnfInstanceId': 'id2',
                        'operationType': 'whatever',
                        'status': 'bad',
                        'startTime': 'long ago'}
        body_content = {'apiVersion': '3.1', 'key': 'value',
                        'vims': [{'accessInfo': {'key': 'value'}}]}
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value=json_content),
                 status_code=202))

        result = self.vnf.instantiate(name='some name',
                                      body_content=body_content,
                                      password='password')

        call_args = self.m_client.send_request.call_args[1]
        actual_data = json.loads(call_args['data'])

        self.assertIsInstance(result, OperationExecution)
        self.assertDictEqual(body_content, actual_data)
        self.m_client.send_request.assert_called_with(
            method='post', endpoint=expected_endpoint,
            api_version='3.1',
            data=ANY)

    def test_givenAllParams_createInstatiateRequestBody_returnsCorrectBody(self):
        file_content = {'apiVersion': '3.1', 'key': 'value',
                        'vims': [{'accessInfo': {'key': 'value'}}]}
        expected_body = {'key': 'value', 'flavourId': 'id',
                         'vims': [{'accessInfo': {'key': 'value', 'password': 'password'}}]}

        output = self.vnf._create_instantiate_request_body(
            body=file_content, password='password', flavour_id='id')
        self.assertDictEqual(expected_body, json.loads(output))

    def test_givenValidArgs_modifyVnf_callsPatchWithCorrectParams(self):
        expected_endpoint = 'vnfm/lcm/v3/vnfs/id'
        expected_data = json.dumps(self.input_data)
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value={'id': 'id',
                                         'vnfInstanceId': 'id',
                                         'operationType': 'type',
                                         'status': 'status',
                                         'startTime': 'startTime'}),
                 status_code=202))

        result = self.vnf.modify(name='some name', parameters_to_change=expected_data)

        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='patch', endpoint=expected_endpoint, data=expected_data)
        self.assertIsInstance(result, OperationExecution)

    def test_givenValidArgs_upgradeVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnfm/lcm/v3/vnfs/id/upgrade'
        expected_data = json.dumps({'vnfdId': 'new_package'})
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value={'id': 'id',
                                    'vnfInstanceId': 'id',
                                    'operationType': 'type',
                                    'status': 'status',
                                    'startTime': 'startTime'}),
            status_code=202))

        result = self.vnf.upgrade(name='some name', vnfd_id='new_package')

        self.assertIsInstance(result, OperationExecution)
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='post', endpoint=expected_endpoint, data=expected_data)

    def test_givenName_terminateVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnfm/lcm/v3/vnfs/id/terminate'
        expected_data = json.dumps({'terminationType': 'GRACEFUL'})
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value={'id': 'id',
                                    'vnfInstanceId': 'id',
                                    'operationType': 'type',
                                    'status': 'status',
                                    'startTime': 'startTime'}),
            status_code=202))

        result = self.vnf.terminate('some name')

        self.assertIsInstance(result, OperationExecution)
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='post', endpoint=expected_endpoint, data=expected_data)

    def test_givenAllParams_terminateVnf_callsPostWithCorrectParams(self):
        self.vnf.terminate('some name', termination_type='GRACEFUL',
                           graceful_termination_timeout=10)
        expected_endpoint = 'vnfm/lcm/v3/vnfs/id/terminate'
        expected_data = json.dumps({'terminationType': 'GRACEFUL',
                                    'gracefulTerminationTimeout': 10})
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='post', endpoint=expected_endpoint, data=expected_data)

    def test_putVimInfo_returnRightParams(self):
        kwargs = {'tenant': 'services', 'password': 'jokertest', 'username': 'joker', 'region': 'RegionTest'}
        data = {"id": 'vim_id',
                "accessInfo": {"tenant": "services", "username": "joker", "password": "jokertest",
                               "region": "RegionTest"},
                "interfaceInfo": {"endpoint": "https://test.org/"},
                "vimInfoType": "OPENSTACK_V2_INFO"}

        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=data), status_code=200))

        vim_info = VimInfo('vim_id', 'OPENSTACK_V2_INFO')
        response = self.vnf.put_vim_info(VnfInfo(name='some name'), vim_info,
                                         'https://test.org/', **kwargs)

        expected_url = 'vnfm/lcm/v3/vnfs/id/vim_info/vim_id'
        actual_version = self.m_client.send_request.call_args[1]['api_version']
        actual_data = json.loads(self.m_client.send_request.call_args[1]['data'])
        actual_url = self.m_client.send_request.call_args[1]['endpoint']
        expected_version = '3.1'

        self.assertEqual(expected_url, actual_url)
        self.assertDictEqual(data, actual_data)
        self.assertEqual(expected_version, actual_version)
        self.assertIsInstance(response, OpenstackV2Info)

    def test_getOperationExecutionInfo_passesWithProperParams(self):
        self.m_client.send_request.return_value = Mock(
            data=self.operation_execution_dict(), status_code=202)
        operation_execution = OperationExecution(operation_id='12345')

        self.vnf.get_operation_execution_info(operation_execution)
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='get', endpoint='vnfm/lcm/v3/operation_executions/12345')

    def _post_custom_operation_test(self, optional_parameter=None):
        output = self.operation_execution_dict()
        status_code = 202
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        if optional_parameter:
            response = self.vnf.post_custom_operation(
                VnfInfo(name='some name'), 'prepare_for_upgrade', {'param1': 'value1'})
            self.m_client.send_request.assert_called_with(
                api_version=None,
                method='post',
                endpoint='vnfm/lcm/v3/vnfs/id/custom/prepare_for_upgrade',
                data='{"additionalParams": {"param1": "value1"}}')
        else:
            response = self.vnf.post_custom_operation(
                VnfInfo(name='some name'), 'prepare_for_upgrade')
            self.m_client.send_request.assert_called_with(
                api_version=None,
                method='post',
                endpoint='vnfm/lcm/v3/vnfs/id/custom/prepare_for_upgrade')

        self.assertIsInstance(response, OperationExecution)

    def test_postCustomOperation_passesWithRequiredParams(self):
        self._post_custom_operation_test()

    def test_postCustomOperation_passesWithAllParams(self):
        self._post_custom_operation_test(optional_parameter=True)

    def test_postCustomOperation_returnsProblemDetails(self):
        output = {'status': 'status', 'detail': 'detail'}
        status_code = 403
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        response = self.vnf.post_custom_operation(
            VnfInfo(name='some name'), 'prepare_for_upgrade')

        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='post',
            endpoint='vnfm/lcm/v3/vnfs/id/custom/prepare_for_upgrade')
        self.assertIsInstance(response, ProblemDetails)

    def test_deleteVnf_whenResponseDoesntHaveJson_returnsNone(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(side_effect=AttributeError), status_code=204))

        vnf = Mock()
        vnf.name = 'some name'
        response = self.vnf.delete_vnf(vnf)

        self.assertIsNone(response)
